/**
 * Model User
 * Users within a tenant — can be Admin, Teacher, Student, or Parent
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Course
 * A course offered by the institute (e.g. "Mathematics Grade 11")
 */
export type Course = $Result.DefaultSelection<Prisma.$CoursePayload>
/**
 * Model Batch
 * A batch is a specific class section within a course (e.g. "2025 Jan Batch")
 */
export type Batch = $Result.DefaultSelection<Prisma.$BatchPayload>
/**
 * Model BatchEnrollment
 * Links students to batches — tracks enrollment status and fee status
 */
export type BatchEnrollment = $Result.DefaultSelection<Prisma.$BatchEnrollmentPayload>
/**
 * Model BatchTeacher
 * Links teachers to batches
 */
export type BatchTeacher = $Result.DefaultSelection<Prisma.$BatchTeacherPayload>
/**
 * Model TimetableSlot
 * Recurring weekly schedule for a batch
 */
export type TimetableSlot = $Result.DefaultSelection<Prisma.$TimetableSlotPayload>
/**
 * Model ContentItem
 * Learning materials attached to courses/batches
 */
export type ContentItem = $Result.DefaultSelection<Prisma.$ContentItemPayload>
/**
 * Model Assignment
 * An assignment created by a teacher for a batch
 */
export type Assignment = $Result.DefaultSelection<Prisma.$AssignmentPayload>
/**
 * Model Submission
 * A student's submission for an assignment
 */
export type Submission = $Result.DefaultSelection<Prisma.$SubmissionPayload>
/**
 * Model AttendanceSession
 * An attendance session for a specific date and timetable slot
 */
export type AttendanceSession = $Result.DefaultSelection<Prisma.$AttendanceSessionPayload>
/**
 * Model AttendanceRecord
 * Individual attendance record per student per session
 */
export type AttendanceRecord = $Result.DefaultSelection<Prisma.$AttendanceRecordPayload>
/**
 * Model Exam
 * An exam (can be online MCQ or manually graded)
 */
export type Exam = $Result.DefaultSelection<Prisma.$ExamPayload>
/**
 * Model ExamQuestion
 * MCQ question for an online exam
 */
export type ExamQuestion = $Result.DefaultSelection<Prisma.$ExamQuestionPayload>
/**
 * Model ExamAttempt
 * A student's attempt at an online exam
 */
export type ExamAttempt = $Result.DefaultSelection<Prisma.$ExamAttemptPayload>
/**
 * Model ExamAnswer
 * Individual answer for each question in an attempt
 */
export type ExamAnswer = $Result.DefaultSelection<Prisma.$ExamAnswerPayload>
/**
 * Model ManualResult
 * Manually entered results (for non-MCQ exams)
 */
export type ManualResult = $Result.DefaultSelection<Prisma.$ManualResultPayload>
/**
 * Model FeeInvoice
 * Fee invoice for a student in a batch
 */
export type FeeInvoice = $Result.DefaultSelection<Prisma.$FeeInvoicePayload>
/**
 * Model Announcement
 * Announcements targeted to specific groups
 */
export type Announcement = $Result.DefaultSelection<Prisma.$AnnouncementPayload>
/**
 * Model Notification
 * Per-user notifications
 */
export type Notification = $Result.DefaultSelection<Prisma.$NotificationPayload>
/**
 * Model ParentStudentLink
 * Associates parent users with their children (student users)
 */
export type ParentStudentLink = $Result.DefaultSelection<Prisma.$ParentStudentLinkPayload>
/**
 * Model Certificate
 * Issued completion certificates
 */
export type Certificate = $Result.DefaultSelection<Prisma.$CertificatePayload>
/**
 * Model AuditLog
 * Immutable audit trail for sensitive operations
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>

